import datetime


def _parse_field(field: str, min_val: int, max_val: int, name_map: dict = None) -> set:
    """Parse a single cron field and return the set of matching values."""
    if name_map is None:
        name_map = {}

    result = set()
    items = field.split(',')

    for item in items:
        item = item.strip()
        if not item:
            raise ValueError(f"Empty item in field: {field!r}")

        # Handle step
        step = 1
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax in field: {item!r}")
            item_part, step_str = parts
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str!r}")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")
        else:
            item_part = item

        # Determine the range to iterate over
        if item_part == '*':
            start = min_val
            end = max_val
        elif '-' in item_part:
            # Range A-B
            range_parts = item_part.split('-')
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range syntax: {item_part!r}")
            a_str, b_str = range_parts
            start = _parse_value(a_str, min_val, max_val, name_map)
            end = _parse_value(b_str, min_val, max_val, name_map)
            if start > end:
                raise ValueError(f"Range start {start} greater than end {end}")
        else:
            # Single value or A/S (which means from A to max)
            val = _parse_value(item_part, min_val, max_val, name_map)
            if '/' in item:
                # A/S means from A to max
                start = val
                end = max_val
            else:
                # Just a single value
                result.add(val)
                continue

        # Add values with step
        for v in range(start, end + 1, step):
            result.add(v)

    return result


def _parse_value(s: str, min_val: int, max_val: int, name_map: dict = None) -> int:
    """Parse a single value (number or name) and validate it's in range."""
    if name_map is None:
        name_map = {}

    s_upper = s.upper()
    if s_upper in name_map:
        val = name_map[s_upper]
    else:
        try:
            val = int(s)
        except ValueError:
            raise ValueError(f"Unknown value: {s!r}")

    if val < min_val or val > max_val:
        raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")

    return val


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Find the next firing time for a standard 5-field cron expression.

    Fields: minute hour day-of-month month day-of-week
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    # Month names
    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }

    # Day names (0 and 7 are both Sunday)
    day_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    # Parse each field
    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    days_of_month = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12, month_names)

    # For day-of-week, we need to handle 0-7 where both 0 and 7 are Sunday
    dow_raw = _parse_field(dow_field, 0, 7, day_names)
    # Normalize: map 7 to 0
    days_of_week = set()
    for d in dow_raw:
        if d == 7:
            days_of_week.add(0)
        else:
            days_of_week.add(d)

    # Determine if dom and dow are restricted (not exactly '*')
    dom_restricted = dom_field.strip() != '*'
    dow_restricted = dow_field.strip() != '*'

    # Start from the next minute after `after`
    current = after.replace(second=0, microsecond=0)
    current += datetime.timedelta(minutes=1)

    # Limit search to 5 years from now
    max_dt = after + datetime.timedelta(days=365 * 5)

    while current <= max_dt:
        if current.month not in months:
            # Skip to next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Check day matching
        dom_match = current.day in days_of_month
        # Python's weekday(): Monday=0, Sunday=6. Cron: Sunday=0, Saturday=6.
        # Convert Python weekday to cron dow: (weekday + 1) % 7
        python_weekday = current.weekday()  # Mon=0 ... Sun=6
        cron_dow = (python_weekday + 1) % 7  # Sun=0, Mon=1, ..., Sat=6
        dow_match = cron_dow in days_of_week

        if dom_restricted and dow_restricted:
            day_matches = dom_match or dow_match
        else:
            day_matches = dom_match and dow_match

        if not day_matches:
            # Skip to next day
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hours:
            # Skip to next hour
            current = (current + datetime.timedelta(hours=1)).replace(minute=0)
            continue

        if current.minute not in minutes:
            # Skip to next minute
            current += datetime.timedelta(minutes=1)
            continue

        return current

    raise ValueError("No matching time found within the next 5 years")
