def merge(base: dict, *overrides: dict) -> dict:
    """Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends: {"plugins+": ["x"]} appends items to base list 'plugins'.
      If base value exists and is not a list, raise TypeError. The '+' key never appears in result.
    - Inputs are not mutated; result is a deep copy (no shared mutable dicts/lists with inputs).
    """

    def _deep_copy(obj):
        """Create a deep copy of obj."""
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        else:
            return obj

    def _merge_into(target: dict, source: dict) -> None:
        """Merge source into target (mutating target). Later keys in source override earlier ones."""
        for key, value in source.items():
            if key.endswith('+'):
                # Append operation
                actual_key = key[:-1]
                if not isinstance(value, list):
                    raise TypeError(f"Value for append key '{key}' must be a list")
                if actual_key in target:
                    existing = target[actual_key]
                    if not isinstance(existing, list):
                        raise TypeError(f"Base value for key '{actual_key}' is not a list, cannot append")
                    # Append items from value to existing list
                    for item in value:
                        existing.append(_deep_copy(item))
                else:
                    # No base value, create new list with the items
                    target[actual_key] = _deep_copy(value)
            elif value is None:
                # Delete key if it exists
                if key in target:
                    del target[key]
            elif isinstance(value, dict):
                # Recursive merge
                if key in target and isinstance(target[key], dict):
                    _merge_into(target[key], value)
                else:
                    target[key] = _deep_copy(value)
            else:
                # Replace with deep copy of the value
                target[key] = _deep_copy(value)

    # Start with a deep copy of base
    result = _deep_copy(base)

    # Merge each override in order
    for override in overrides:
        _merge_into(result, override)

    return result
