def parse_duration(s: str) -> int:
    """Parse a human-readable duration string into seconds."""
    if not s or not s.strip():
        raise ValueError("Empty input")

    # Units in order: d, h, m, s
    units_order = {'d': 3, 'h': 2, 'm': 1, 's': 0}
    unit_seconds = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    total = 0
    i = 0
    n = len(s)

    seen_units = set()
    last_unit_index = -1  # To track ordering

    first_part = True

    while i < n:
        # Skip exactly one space if present (only between parts, not at start or double spaces)
        if s[i] == ' ':
            if first_part:
                raise ValueError("Leading space")
            i += 1
            # After a space, the next character must be a digit (start of a new part)
            if i >= n or s[i] != s[i].isdigit():
                raise ValueError("Invalid format after space")
        else:
            if not first_part:
                # If we're not at the start and there's no space, that's fine for concatenated parts like "1h30m"
                pass

        # Read the number
        num_start = i
        while i < n and s[i].isdigit():
            i += 1

        if i == num_start:
            raise ValueError("Missing number")

        number = int(s[num_start:i])

        # Read the unit
        if i >= n:
            raise ValueError("Missing unit")

        unit_char = s[i].lower()
        i += 1

        if unit_char not in units_order:
            raise ValueError(f"Unknown unit: {unit_char}")

        if unit_char in seen_units:
            raise ValueError(f"Repeated unit: {unit_char}")

        current_unit_index = units_order[unit_char]

        # Check ordering: each unit must come after the previous one (strictly decreasing index means correct order)
        # d=3, h=2, m=1, s=0. So we need current < last for valid order
        if last_unit_index != -1 and current_unit_index >= last_unit_index:
            raise ValueError("Wrong unit order")

        seen_units.add(unit_char)
        last_unit_index = current_unit_index

        total += number * unit_seconds[unit_char]

        first_part = False

    # Check that we consumed the entire string properly
    if not seen_units:
        raise ValueError("No valid duration parts found")

    return total


def format_duration(seconds: int) -> str:
    """Format seconds into a human-readable duration string."""
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    days = seconds // 86400
    remainder = seconds % 86400
    hours = remainder // 3600
    remainder = remainder % 3600
    minutes = remainder // 60
    secs = remainder % 60

    parts = []
    if days > 0:
        parts.append(f"{days}d")
    if hours > 0:
        parts.append(f"{hours}h")
    if minutes > 0:
        parts.append(f"{minutes}m")
    if secs > 0:
        parts.append(f"{secs}s")

    return ''.join(parts)
