def flatten(obj, sep=".") -> dict:
    if not isinstance(obj, dict):
        raise TypeError("top-level object must be a dict")

    result = {}

    def _flatten(key_prefix, value):
        # Check key validity for non-leaf keys
        if isinstance(value, dict) and len(value) > 0:
            for k, v in value.items():
                if not isinstance(k, str):
                    raise ValueError("keys must be strings")
                if sep in k:
                    raise ValueError(f"key '{k}' contains separator '{sep}'")
                new_key = f"{key_prefix}{sep}{k}" if key_prefix else k
                _flatten(new_key, v)
        elif isinstance(value, list) and len(value) > 0:
            for i, item in enumerate(value):
                new_key = f"{key_prefix}{sep}{i}" if key_prefix else str(i)
                _flatten(new_key, item)
        else:
            # Leaf value (including empty dict, empty list, or any other value)
            result[key_prefix] = value

    for k, v in obj.items():
        if not isinstance(k, str):
            raise ValueError("keys must be strings")
        if sep in k:
            raise ValueError(f"key '{k}' contains separator '{sep}'")
        _flatten(k, v)

    return result


def unflatten(flat: dict, sep="."):
    if not isinstance(flat, dict):
        raise TypeError("input must be a dict")

    # We'll build up the structure. Use a trie-like approach or recursive building.
    # First, let's collect all keys and validate them.

    def _is_valid_index(s):
        """Check if s is a valid non-negative integer without leading zeros."""
        if not isinstance(s, str):
            return False
        if len(s) == 0:
            return False
        if not s.isdigit():
            return False
        # No leading zeros unless it's just "0"
        if len(s) > 1 and s[0] == '0':
            return False
        return True

    # Build the tree structure
    # Each node is either a dict, a list, or a leaf value.

    root = {}

    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("keys must be strings")

        parts = key.split(sep)

        # Navigate/create the path
        current = root
        for i, part in enumerate(parts[:-1]):
            is_last = False  # This is not the last part
            if isinstance(current, dict):
                if part in current:
                    existing = current[part]
                    # If existing is a leaf (not dict or list), conflict
                    if not isinstance(existing, (dict, list)):
                        raise ValueError(f"conflict at key '{key}'")
                    current = existing
                else:
                    # Determine what to create based on the next part
                    next_part = parts[i + 1]
                    if _is_valid_index(next_part):
                        # Create a list
                        new_list = {}
                        current[part] = new_list
                        current = new_list
                    else:
                        # Create a dict
                        new_dict = {}
                        current[part] = new_dict
                        current = new_dict
            elif isinstance(current, list):
                # current is a list (stored as dict internally for building)
                if part in current:
                    existing = current[part]
                    if not isinstance(existing, (dict, list)):
                        raise ValueError(f"conflict at key '{key}'")
                    current = existing
                else:
                    next_part = parts[i + 1]
                    if _is_valid_index(next_part):
                        new_list = {}
                        current[part] = new_list
                        current = new_list
                    else:
                        new_dict = {}
                        current[part] = new_dict
                        current = new_dict
            else:
                raise ValueError(f"conflict at key '{key}'")

        # Set the leaf value
        last_part = parts[-1]
        if isinstance(current, dict):
            if last_part in current:
                existing = current[last_part]
                if isinstance(existing, (dict, list)) and len(existing) > 0:
                    raise ValueError(f"conflict at key '{key}'")
                # If it's an empty container, we can replace it with a leaf
            current[last_part] = value
        elif isinstance(current, list):
            if last_part in current:
                existing = current[last_part]
                if isinstance(existing, (dict, list)) and len(existing) > 0:
                    raise ValueError(f"conflict at key '{key}'")
            current[last_part] = value

    # Now convert the internal representation to proper lists/dicts
    def _convert(node):
        if isinstance(node, dict):
            # Check if this should be a list
            if len(node) == 0:
                return {}

            keys = list(node.keys())
            # Check if all keys are valid indices
            all_indices = all(_is_valid_index(k) for k in keys)
            if all_indices:
                # Should be a list
                indices = [int(k) for k in keys]
                n = len(indices)
                # Check that indices are exactly 0..n-1
                expected = set(range(n))
                actual = set(indices)
                if actual != expected:
                    raise ValueError("list indices must be dense (0..n-1)")
                result_list = [None] * n
                for k, v in node.items():
                    idx = int(k)
                    result_list[idx] = _convert(v)
                return result_list
            else:
                # Should be a dict
                result_dict = {}
                for k, v in node.items():
                    result_dict[k] = _convert(v)
                return result_dict
        elif isinstance(node, list):
            return [_convert(item) for item in node]
        else:
            return node

    # Handle the case where root might need to be converted
    # Root is always a dict in our internal representation
    if len(root) == 0:
        return {}

    keys = list(root.keys())
    all_indices = all(_is_valid_index(k) for k in keys)
    if all_indices:
        indices = [int(k) for k in keys]
        n = len(indices)
        expected = set(range(n))
        actual = set(indices)
        if actual != expected:
            raise ValueError("list indices must be dense (0..n-1)")
        result_list = [None] * n
        for k, v in root.items():
            idx = int(k)
            result_list[idx] = _convert(v)
        return result_list
    else:
        result_dict = {}
        for k, v in root.items():
            result_dict[k] = _convert(v)
        return result_dict
