def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        # Number
        if c.isdigit() or (c == '.' and i + 1 < n and expr[i + 1].isdigit()):
            j = i
            is_float = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    is_float = True
                j += 1
            num_str = expr[i:j]
            if is_float:
                tokens.append(('NUM', float(num_str)))
            else:
                tokens.append(('NUM', int(num_str)))
            i = j
            continue
        # Identifier
        if c.isalpha() or c == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(('IDENT', expr[i:j]))
            i = j
            continue
        # Two-char operators
        if i + 1 < n:
            two = expr[i:i+2]
            if two in ('==', '!=', '<=', '>=', '||', '&&'):
                tokens.append(('OP', two))
                i += 2
                continue
        # Single-char operators and delimiters
        if c in '+-*/%^!<>=?:()|&':
            tokens.append(('OP', c))
            i += 1
            continue
        raise SyntaxError(f"Unexpected character: {c}")

    if not tokens:
        raise SyntaxError("Empty expression")

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def next_token():
        tok = peek()
        if tok is None:
            raise SyntaxError("Unexpected end of input")
        pos[0] += 1
        return tok

    def expect_op(op_str):
        tok = next_token()
        if tok[0] != 'OP' or tok[1] != op_str:
            raise SyntaxError(f"Expected {op_str}, got {tok}")

    def parse_conditional():
        # a ? b : c, right-associative
        left = parse_or()
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] == '?':
            next_token()  # consume ?
            middle = parse_conditional()
            expect_op(':')
            right = parse_conditional()
            return left if left != 0 else right
        return left

    def parse_or():
        # ||, short-circuit
        left = parse_and()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] == '||':
                next_token()
                right = parse_and()
                left = 1 if (left != 0 or right != 0) else 0
            else:
                break
        return left

    def parse_and():
        # &&, short-circuit
        left = parse_comparison()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] == '&&':
                next_token()
                right = parse_comparison()
                left = 1 if (left != 0 and right != 0) else 0
            else:
                break
        return left

    def parse_comparison():
        # Non-associative comparisons
        left = parse_additive()
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = tok[1]
            next_token()
            right = parse_additive()
            # Check for non-associativity: if next token is another comparison, error
            nxt = peek()
            if nxt is not None and nxt[0] == 'OP' and nxt[1] in ('==', '!=', '<', '<=', '>', '>='):
                raise SyntaxError("Non-associative comparison")
            if op == '==':
                return 1 if left == right else 0
            elif op == '!=':
                return 1 if left != right else 0
            elif op == '<':
                return 1 if left < right else 0
            elif op == '<=':
                return 1 if left <= right else 0
            elif op == '>':
                return 1 if left > right else 0
            elif op == '>=':
                return 1 if left >= right else 0
        return left

    def parse_additive():
        # + -, left-associative
        left = parse_multiplicative()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] in ('+', '-'):
                op = tok[1]
                next_token()
                right = parse_multiplicative()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_multiplicative():
        # * / %, left-associative
        left = parse_power()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] in ('*', '/', '%'):
                op = tok[1]
                next_token()
                right = parse_power()
                if op == '*':
                    left = left * right
                elif op == '/':
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    # / on two ints gives int when it divides exactly, else float
                    if isinstance(left, int) and isinstance(right, int):
                        if left % right == 0:
                            left = left // right
                        else:
                            left = left / right
                    else:
                        left = left / right
                elif op == '%':
                    if right == 0:
                        raise ZeroDivisionError("modulo by zero")
                    left = left % right
            else:
                break
        return left

    def parse_power():
        # ^, right-associative. Binds tighter than unary minus on its left.
        # -2^2 is -4, 2^-1 is 0.5, 2^3^2 is 512
        base = parse_unary()
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] == '^':
            next_token()
            # Right-associative: parse exponent as power (not unary) to handle 2^3^2
            # But we need to allow unary in the exponent for 2^-1
            exponent = parse_power_right()
            return base ** exponent
        return base

    def parse_power_right():
        # For right-associative parsing of power, the exponent should be a power expression
        # but also allow unary minus/plus in the exponent (e.g., 2^-1)
        # Actually, let's think about this more carefully.
        # -2^2 = -(2^2) = -4
        # 2^-1 = 2^(-1) = 0.5
        # 2^3^2 = 2^(3^2) = 512
        # So the base of ^ is a unary expression (which can include -), and the exponent is...
        # If we parse exponent as parse_power, then 2^-1: base=2, see ^, parse_power_right
        # parse_power_right calls parse_unary which sees -, so it handles it.
        # But for 2^3^2: base=2, see ^, parse_power_right -> parse_unary gets 3, then sees ^, 
        # so it becomes 3^(parse_power_right) = 3^2 = 9, so 2^9 = 512. Good.

        # Wait, but parse_power calls parse_unary for base, then if ^, calls parse_power_right.
        # parse_power_right should parse a unary expression that can itself be a power.
        # Actually, the cleanest way: exponent is parsed as parse_unary, but if that unary 
        # result is followed by ^, we need right-associativity. 
        # Let me restructure: parse_power handles the left side as unary, then if ^, 
        # the right side should be a "power" expression (right-associative).

        # So parse_power_right should essentially be: parse_unary, and if ^, recurse on power.
        base = parse_unary()
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] == '^':
            next_token()
            exponent = parse_power_right()
            return base ** exponent
        return base

    def parse_unary():
        # unary -, +, !
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] in ('-', '+', '!'):
            op = tok[1]
            next_token()
            operand = parse_unary()  # right-associative unary
            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            elif op == '!':
                return 1 if operand == 0 else 0
        return parse_atom()

    def parse_atom():
        tok = peek()
        if tok is None:
            raise SyntaxError("Unexpected end of input")

        if tok[0] == 'NUM':
            next_token()
            return tok[1]

        if tok[0] == 'IDENT':
            name = tok[1]
            next_token()
            # Check for function call
            nxt = peek()
            if nxt is not None and nxt[0] == 'OP' and nxt[1] == '(':
                next_token()  # consume (
                args = []
                # Check for empty args
                cur = peek()
                if cur is not None and cur[0] == 'OP' and cur[1] == ')':
                    next_token()  # consume )
                    # No arguments
                else:
                    while True:
                        arg = parse_conditional()
                        args.append(arg)
                        cur = peek()
                        if cur is not None and cur[0] == 'OP' and cur[1] == ',':
                            next_token()  # consume ,
                            continue
                        elif cur is not None and cur[0] == 'OP' and cur[1] == ')':
                            next_token()  # consume )
                            break
                        else:
                            raise SyntaxError("Expected ',' or ')' in function call")

                if name == 'abs':
                    if len(args) != 1:
                        raise SyntaxError("abs expects exactly 1 argument")
                    return abs(args[0])
                elif name == 'min':
                    if len(args) < 1:
                        raise SyntaxError("min expects at least 1 argument")
                    return min(args)
                elif name == 'max':
                    if len(args) < 1:
                        raise SyntaxError("max expects at least 1 argument")
                    return max(args)
                else:
                    raise NameError(f"Unknown function: {name}")
            else:
                # Variable lookup
                if name not in env:
                    raise NameError(f"Unknown variable: {name}")
                return env[name]

        if tok[0] == 'OP' and tok[1] == '(':
            next_token()  # consume (
            val = parse_conditional()
            expect_op(')')
            return val

        raise SyntaxError(f"Unexpected token: {tok}")

    result = parse_conditional()

    # Check for trailing tokens
    if pos[0] < len(tokens):
        raise SyntaxError(f"Trailing tokens: {tokens[pos[0]]}")

    return result
