import re
from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # list of identifiers or None
        self.build = build  # list of identifiers or None

    def _precedence_key(self):
        # SemVer precedence:
        # - Build metadata ignored
        # - Major, minor, patch compared numerically
        # - Prerelease < release
        # - Prerelease identifiers compared per rules
        return (self.major, self.minor, self.patch, self._prerelease_key())

    def _prerelease_key(self):
        if self.prerelease is None:
            # Release version: higher than any prerelease
            return (1,)  # Use a tuple that sorts after any prerelease key
        else:
            # Prerelease: sort before release
            # Each identifier: numeric identifiers compared numerically,
            # numeric < alphanumeric, alphanumeric in ASCII order
            ids = []
            for ident in self.prerelease:
                if re.match(r'^[0-9]+$', ident):
                    # Numeric identifier
                    ids.append((0, int(ident), ''))
                else:
                    # Alphanumeric identifier
                    ids.append((1, 0, ident))
            return (0, tuple(ids))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._precedence_key() == other._precedence_key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._precedence_key() < other._precedence_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._precedence_key() <= other._precedence_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._precedence_key() > other._precedence_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._precedence_key() >= other._precedence_key()

    def __hash__(self):
        return hash(self._precedence_key())

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += "-" + ".".join(self.prerelease)
        if self.build is not None:
            s += "+" + ".".join(self.build)
        return s


def _parse_prerelease(s):
    """Parse prerelease string into list of identifiers."""
    parts = s.split('.')
    for p in parts:
        if not p:
            raise ValueError("Empty prerelease identifier")
        if not re.match(r'^[0-9A-Za-z-]+$', p):
            raise ValueError(f"Invalid prerelease identifier: {p}")
        # No leading zeros in numeric identifiers
        if re.match(r'^[0-9]+$', p) and len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zero in numeric prerelease identifier: {p}")
    return parts


def _parse_build(s):
    """Parse build metadata string into list of identifiers."""
    parts = s.split('.')
    for p in parts:
        if not p:
            raise ValueError("Empty build identifier")
        if not re.match(r'^[0-9A-Za-z-]+$', p):
            raise ValueError(f"Invalid build identifier: {p}")
    return parts


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    s = v.strip()
    # Allow leading 'v' or '='
    if s.startswith('v'):
        s = s[1:]
    elif s.startswith('='):
        s = s[1:]

    # Split off build metadata
    plus_idx = s.find('+')
    build_str = None
    if plus_idx != -1:
        build_str = s[plus_idx + 1:]
        s = s[:plus_idx]

    # Split off prerelease
    dash_idx = s.find('-')
    prerelease_str = None
    if dash_idx != -1:
        prerelease_str = s[dash_idx + 1:]
        s = s[:dash_idx]

    # Parse major.minor.patch
    parts = s.split('.')
    if len(parts) < 1 or len(parts) > 3:
        raise ValueError(f"Invalid version format: {v}")

    def parse_numeric(part, name):
        if not part:
            raise ValueError(f"Empty {name}")
        if not re.match(r'^[0-9]+$', part):
            raise ValueError(f"Invalid {name}: {part}")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zero in {name}: {part}")
        return int(part)

    major = parse_numeric(parts[0], "major")
    if len(parts) >= 2:
        minor = parse_numeric(parts[1], "minor")
    else:
        minor = 0
    if len(parts) >= 3:
        patch = parse_numeric(parts[2], "patch")
    else:
        patch = 0

    prerelease = None
    if prerelease_str is not None:
        prerelease = _parse_prerelease(prerelease_str)

    build = None
    if build_str is not None:
        build = _parse_build(build_str)

    return Version(major, minor, patch, prerelease, build)


class Comparator:
    """Represents a single comparator like >=1.2.3"""
    def __init__(self, op, version):
        self.op = op  # '<', '<=', '>', '>=', '='
        self.version = version

    def test(self, v: Version) -> bool:
        if self.op == '<':
            return v < self.version
        elif self.op == '<=':
            return v <= self.version
        elif self.op == '>':
            return v > self.version
        elif self.op == '>=':
            return v >= self.version
        else:  # '='
            return v == self.version


class ComparatorSet:
    """A set of comparators that must all match."""
    def __init__(self, comparators):
        self.comparators = comparators

    def test(self, v: Version) -> bool:
        # Prerelease rule: if v has a prerelease, at least one comparator
        # in this set must have a version with the same MAJOR.MINOR.PATCH
        # and a prerelease.
        if v.prerelease is not None:
            has_matching_prerelease = False
            for c in self.comparators:
                if (c.version.major == v.major and
                    c.version.minor == v.minor and
                    c.version.patch == v.patch and
                    c.version.prerelease is not None):
                    has_matching_prerelease = True
                    break
            if not has_matching_prerelease:
                return False

        # All comparators must match
        for c in self.comparators:
            if not c.test(v):
                return False
        return True


def _is_xrange(part):
    """Check if a version part is an X-range (x, X, *, or empty)."""
    return part in ('x', 'X', '*', '')


def _expand_comparator(op, major, minor, patch, has_minor, has_patch):
    """Expand a partial version with operator into full comparators."""
    # Determine what's specified
    # major is always present (or x)

    if op in ('<', '<='):
        # < and <=: for partial versions, the unspecified parts are treated as 0
        # <1.2 means <1.2.0
        # <=1.2 means <1.3.0
        # <1 means <1.0.0
        # <=1 means <2.0.0

        if not has_patch:
            if not has_minor:
                # Just major specified, e.g., <1 or <=1
                if op == '<':
                    return [Comparator('<', Version(major, 0, 0))]
                else:  # <=
                    return [Comparator('<', Version(major + 1, 0, 0))]
            else:
                # Major and minor specified, e.g., <1.2 or <=1.2
                if op == '<':
                    return [Comparator('<', Version(major, minor, 0))]
                else:  # <=
                    return [Comparator('<', Version(major, minor + 1, 0))]
        else:
            # Full version specified
            if op == '<':
                return [Comparator('<', Version(major, minor, patch))]
            else:  # <=
                return [Comparator('<=', Version(major, minor, patch))]

    elif op in ('>', '>='):
        # > and >=: for partial versions, the unspecified parts are treated as 0
        # but the range starts from the next value if it's a strict inequality
        # >1.2 means >=1.3.0
        # >=1.2 means >=1.2.0
        # >1 means >=2.0.0
        # >=1 means >=1.0.0

        if not has_patch:
            if not has_minor:
                # Just major specified, e.g., >1 or >=1
                if op == '>':
                    return [Comparator('>=', Version(major + 1, 0, 0))]
                else:  # >=
                    return [Comparator('>=', Version(major, 0, 0))]
            else:
                # Major and minor specified, e.g., >1.2 or >=1.2
                if op == '>':
                    return [Comparator('>=', Version(major, minor + 1, 0))]
                else:  # >=
                    return [Comparator('>=', Version(major, minor, 0))]
        else:
            # Full version specified
            if op == '>':
                return [Comparator('>', Version(major, minor, patch))]
            else:  # >=
                return [Comparator('>=', Version(major, minor, patch))]

    elif op == '=' or op is None:
        # = or no operator: X-range expansion
        if not has_patch:
            if not has_minor:
                # Just major specified, e.g., 1 or =1
                return [Comparator('>=', Version(major, 0, 0)),
                        Comparator('<', Version(major + 1, 0, 0))]
            else:
                # Major and minor specified, e.g., 1.2 or =1.2
                return [Comparator('>=', Version(major, minor, 0)),
                        Comparator('<', Version(major, minor + 1, 0))]
        else:
            # Full version specified
            return [Comparator('=', Version(major, minor, patch))]

    raise ValueError(f"Unknown operator: {op}")


def _parse_version_parts(s):
    """Parse a version string (possibly partial) into (major, minor, patch, has_minor, has_patch)."""
    s = s.strip()

    # Allow leading 'v' or '='
    if s.startswith('v'):
        s = s[1:]
    elif s.startswith('='):
        s = s[1:]

    # Split off build metadata (ignore for range purposes)
    plus_idx = s.find('+')
    if plus_idx != -1:
        s = s[:plus_idx]

    # Split off prerelease
    dash_idx = s.find('-')
    prerelease_str = None
    if dash_idx != -1:
        prerelease_str = s[dash_idx + 1:]
        s = s[:dash_idx]

    parts = s.split('.')

    def parse_part(part, name):
        if _is_xrange(part):
            return None
        if not part:
            raise ValueError(f"Empty {name}")
        if not re.match(r'^[0-9]+$', part):
            raise ValueError(f"Invalid {name}: {part}")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zero in {name}: {part}")
        return int(part)

    major_val = parse_part(parts[0], "major")
    if major_val is None:
        # X-range for major: matches anything
        return (None, None, None, False, False)

    has_minor = len(parts) >= 2
    minor_val = None
    if has_minor:
        minor_val = parse_part(parts[1], "minor")
        if minor_val is None:
            # X-range for minor
            return (major_val, None, None, True, False)

    has_patch = len(parts) >= 3
    patch_val = None
    if has_patch:
        patch_val = parse_part(parts[2], "patch")
        if patch_val is None:
            # X-range for patch
            return (major_val, minor_val, None, True, False)

    prerelease = None
    if prerelease_str is not None:
        prerelease = _parse_prerelease(prerelease_str)

    return (major_val, minor_val, patch_val, has_minor, has_patch, prerelease)


def _expand_tilde(major, minor, patch, has_minor, has_patch):
    """Expand tilde range."""
    if not has_patch:
        if not has_minor:
            # ~1 => >=1.0.0 <2.0.0
            return [Comparator('>=', Version(major, 0, 0)),
                    Comparator('<', Version(major + 1, 0, 0))]
        else:
            # ~1.2 => >=1.2.0 <1.3.0
            return [Comparator('>=', Version(major, minor, 0)),
                    Comparator('<', Version(major, minor + 1, 0))]
    else:
        # ~1.2.3 => >=1.2.3 <1.3.0
        return [Comparator('>=', Version(major, minor, patch)),
                Comparator('<', Version(major, minor + 1, 0))]


def _expand_caret(major, minor, patch, has_minor, has_patch):
    """Expand caret range."""
    if not has_patch:
        if not has_minor:
            # ^1 => >=1.0.0 <2.0.0 (if major > 0) or >=0.0.0 <1.0.0 (if major == 0)
            if major is None:
                # ^x or ^* => any version
                return [Comparator('>=', Version(0, 0, 0))]
            if major == 0:
                return [Comparator('>=', Version(0, 0, 0)),
                        Comparator('<', Version(1, 0, 0))]
            else:
                return [Comparator('>=', Version(major, 0, 0)),
                        Comparator('<', Version(major + 1, 0, 0))]
        else:
            # ^1.2 => >=1.2.0 <2.0.0 (if major > 0) or >=0.2.0 <0.3.0 (if major == 0)
            if major is None:
                return [Comparator('>=', Version(0, 0, 0))]
            if major == 0:
                return [Comparator('>=', Version(0, minor, 0)),
                        Comparator('<', Version(0, minor + 1, 0))]
            else:
                return [Comparator('>=', Version(major, minor, 0)),
                        Comparator('<', Version(major + 1, 0, 0))]
    else:
        # Full version specified
        if major is None:
            return [Comparator('>=', Version(0, 0, 0))]
        if major > 0:
            upper = (major + 1, 0, 0)
        elif minor > 0:
            upper = (0, minor + 1, 0)
        else:
            upper = (0, 0, patch + 1)
        return [Comparator('>=', Version(major, minor, patch)),
                Comparator('<', Version(upper[0], upper[1], upper[2]))]


def _parse_comparator_set(s):
    """Parse a comparator set (whitespace-separated comparators)."""
    s = s.strip()
