set -euo pipefail

usage() {
    echo "Usage: $0 [-n N] [-i]" >&2
    exit 2
}

N=10
IGNORE_CASE=0

while getopts ":n:i" opt; do
    case "$opt" in
        n)
            N=$OPTARG
            # Validate N is a positive integer
            if ! [[ $N =~ ^[0-9]+$ ]] || [ "$N" -le 0 ]; then
                usage
            fi
            ;;
        i)
            IGNORE_CASE=1
            ;;
        :)
            echo "Option -$OPTARG requires an argument." >&2
            usage
            ;;
        \?)
            echo "Invalid option: -$OPTARG" >&2
            usage
            ;;
    esac
done

# Read all input
input=$(cat)

# If empty input, print nothing and exit 0
if [ -z "$input" ]; then
    exit 0
fi

# Process with awk
LC_ALL=C awk -v n="$N" -v ignore_case="$IGNORE_CASE" '
BEGIN {
    # Nothing special needed in BEGIN for mawk
}
{
    # Split into tokens: a word is a maximal run of [a-zA-Z0-9] (and apostrophes)
    # We need to extract all runs of [A-Za-z0-9\x27]+ from each line
    # Since mawk doesn\x27t have gensub, we\x27ll use a manual approach

    line = $0
    len = length(line)

    i = 1
    while (i <= len) {
        c = substr(line, i, 1)
        if (c ~ /[A-Za-z0-9\x27]/) {
            # Start of a token
            j = i
            while (j <= len) {
                cj = substr(line, j, 1)
                if (cj ~ /[A-Za-z0-9\x27]/) {
                    j++
                } else {
                    break
                }
            }
            token = substr(line, i, j - i)

            # Strip leading and trailing apostrophes
            while (length(token) > 0 && substr(token, 1, 1) == "\x27") {
                token = substr(token, 2)
            }
            while (length(token) > 0 && substr(token, length(token), 1) == "\x27") {
                token = substr(token, 1, length(token) - 1)
            }

            # If token is empty or only apostrophes, ignore it
            if (length(token) > 0) {
                # Check if token is only apostrophes
                only_apos = 1
                for (k = 1; k <= length(token); k++) {
                    ck = substr(token, k, 1)
                    if (ck != "\x27") {
                        only_apos = 0
                        break
                    }
                }

                if (!only_apos) {
                    if (ignore_case == 1) {
                        token = tolower(token)
                    }
                    count[token]++
                }
            }

            i = j
        } else {
            i++
        }
    }
}
END {
    # We need to sort by count descending, then word ascending (byte order)
    # mawk doesn\x27t have asort, so we\x27ll output "COUNT WORD" lines and pipe to sort

    for (word in count) {
        printf "%d %s\n", count[word], word
    }
}
' <<< "$input" | LC_ALL=C sort -k1,1nr -k2,2 | head -n "$N"
